      "content": "import fs from 'node:fs/promises';
import path from 'node:path';

const STORE_PATH = path.resolve(process.cwd(), 'data', 'jobs-store.json');

/**
 * Simple JSON file-based store with atomic writes.
 * Structure: {
 *  "pending": { jobId: { payload, createdAt } },
 *  "completed": { jobId: { payload, status, result, completedAt } },
 *  "failed": { jobId: { payload, error, completedAt } }
 * }
 */
class Store {
  static async read() {
    try {
      const data = await fs.readFile(STORE_PATH, 'utf-8');
      return JSON.parse(data);
    } catch (err) {
      if (err.code === 'ENOENT') return { pending: {}, completed: {}, failed: {} };
      throw err;
    }
  }

  static async write(data) {
    const dir = path.dirname(STORE_PATH);
    await fs.mkdir(dir, { recursive: true });
    const tmpPath = STORE_PATH + '.tmp';
    await fs.writeFile(tmpPath, JSON.stringify(data, null, 2), 'utf-8');
    await fs.rename(tmpPath, STORE_PATH);
  }

  static pendingKey(jobId) { return `pending:${jobId}`; }
  static completedKey(jobId) { return `completed:${jobId}`; }
  static failedKey(jobId) { return `failed:${jobId}`; }
}

export default Store;
