      "content": "import Store from './store.js';
import fs from 'node:fs/promises';
import path from 'node:path';

const APPLY_LOG_PATH = path.resolve(process.cwd(), 'data', 'apply-log.json');

/**
 * Applies a job with idempotency and persistence.
 * - Records pending state before execution
 * - Executes payload as async function
 * - On success: moves to completed with result
 * - On failure: moves to failed with error
 * - Resumes from pending on restart
 */
class Apply {
  static async apply(jobId, payload, store) {
    const storeData = await Store.read();

    // Check if already completed
    if (storeData.completed[jobId]) {
      return { status: 'completed', result: storeData.completed[jobId].result };
    }

    // Check if in pending or failed (resumable)
    if (storeData.pending[jobId] || storeData.failed[jobId]) {
      return { status: 'resumed', previous: storeData.pending[jobId] || storeData.failed[jobId] };
    }

    // Mark as pending
    storeData.pending[jobId] = { payload, createdAt: new Date().toISOString() };
    await Store.write(storeData);

    // Execute payload
    try {
      const result = await payload();
      const successData = {
        ...storeData,
        completed: { ...storeData.completed, [jobId]: { payload, result, completedAt: new Date().toISOString() } },
        pending: { ...storeData.pending, [jobId]: undefined },
        failed: storeData.failed
      };
      await Store.write(successData);
      return { status: 'completed', result };
    } catch (err) {
      const failureData = {
        ...storeData,
        failed: { ...storeData.failed, [jobId]: { payload, error: err.message, completedAt: new Date().toISOString() } },
        pending: { ...storeData.pending, [jobId]: undefined },
        completed: storeData.completed
      };
      await Store.write(failureData);
      throw err;
    }
  }
}

export default Apply;
